function lineupOrders(players) {
  const perms = (items) => items.length === 0 ? [[]]
    : items.flatMap((x, i) => perms([...items.slice(0, i), ...items.slice(i + 1)]).map((p) => [x, ...p]));
  return perms(players).sort((a, b) => {
    for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return a[i] - b[i];
    return 0;
  });
}

function lineupOrders(players) {
  const sorted = [...players].sort((a, b) => a - b);
  const used = sorted.map(() => false), current = [], result = [];
  const place = () => {
    if (current.length === sorted.length) { result.push([...current]); return; }
    for (let i = 0; i < sorted.length; i++) {
      if (used[i]) continue;
      used[i] = true;
      current.push(sorted[i]);
      place();
      current.pop();
      used[i] = false;
    }
  };
  place();
  return result;
}
